package run.ikaros.notes; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PrivateTagService{private final PrivateVaultRepository vaults;private final PrivateTagRepository tags;public PrivateTagService(PrivateVaultRepository v,PrivateTagRepository t){vaults=v;tags=t;}public Mono<PrivateTagView> create(UUID a,UUID v,CreatePrivateTagRequest q){return own(a,v).flatMap(x->tags.save(new PrivateTagEntity(null,v,a,q.encryptedName(),null))).map(this::view);}public Flux<PrivateTagView> list(UUID a,UUID v){return own(a,v).flatMapMany(x->tags.findAllByVaultIdAndOwnerIdOrderByIdAsc(v,a).map(this::view));}private Mono<PrivateVaultEntity> own(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Private Vault 不存在或无权访问")));}private PrivateTagView view(PrivateTagEntity t){return new PrivateTagView(t.id(),t.vaultId(),t.encryptedName());}}
